+        this.inferenceEntityId = model.getInferenceEntityId();
+        this.isOpenAiRequest = (model.provider() == AzureAiStudioProvider.OPENAI);
+        this.isRealtimeEndpoint = (model.endpointType() == AzureAiStudioEndpointType.REALTIME);
